solutionCode:
#[derive(Debug, PartialEq, Clone, Copy)]
pub struct Ponto {
    pub x: i32,
    pub y: i32,
}

pub fn ponto_de(x: i32, y: i32) -> Ponto {
    Ponto { x: x, y: y }
}

pub fn dobra_e_devolve(p: Ponto) -> i32 {
    let copia = p;
    p.x + copia.x
}

testsCode:
use desafio::dobra_e_devolve;
use desafio::ponto_de;

#[test]
fn testa_o_ponto_dois_por_tres_sobrevive_a_copia() {
    assert_eq!(dobra_e_devolve(ponto_de(2, 3)), 4);
}

#[test]
fn testa_o_ponto_origem_sobrevive_a_copia() {
    assert_eq!(dobra_e_devolve(ponto_de(0, 0)), 0);
}
